// Optional descriptive market statistics, never an input to rankings or settlement.
function nextDayMarketStatistics(sourceRows, start, reportDate, asOf, dailyTables) {
  const rows = sourceRows.filter(r => r.signal_date >= start && r.signal_date <= reportDate && r.signal_date <= asOf);
  const records = rows.map(row => {
    if (row.exec_date > asOf) return { rank:Number(row.promotion_rank), status:"pending" };
    const quotes = (dailyTables.get(row.exec_date) || []).filter(q => q.ts_code === row.ts_code && q.trade_date === row.exec_date);
    const q = quotes.length === 1 ? quotes[0] : null;
    const positive = v => v != null && String(v).trim() !== "" && Number.isFinite(Number(v)) && Number(v) > 0;
    // Missing, duplicate, invalid and suspended quotes do not become zero returns.
    if (!q || ![q.close,q.pre_close,q.vol].every(positive)) return { rank:Number(row.promotion_rank), status:"missing" };
    const change = Number(q.close) / Number(q.pre_close) - 1;
    return Number.isFinite(change) ? {rank:Number(row.promotion_rank),status:"valid",change} : {rank:Number(row.promotion_rank),status:"missing"};
  });
  return [1,2,3,"all"].map(rank => {
    const group = records.filter(r => rank === "all" || r.rank === rank);
    const values = group.filter(r => r.status === "valid").map(r => r.change).sort((a,b) => a-b);
    const n = values.length, up = values.filter(v => v > 0).length;
    return {rank,count:group.length,valid:n,up,pending:group.filter(r => r.status === "pending").length,
      missing:group.filter(r => r.status === "missing").length,upRate:n ? up/n : null,
      mean:n ? values.reduce((a,b) => a+b,0)/n : null,
      median:n ? (values[Math.floor((n-1)/2)] + values[Math.floor(n/2)])/2 : null};
  });
}

async function loadNextDayMarketStatistics({sourceRows, summary, payload}) {
  const days = [...new Set(sourceRows.filter(r => r.signal_date >= payload.start_signal_date && r.signal_date <= payload.report_signal_date && r.signal_date <= summary.as_of_date && r.exec_date <= summary.as_of_date).map(r => r.exec_date))];
  const tables = new Map();
  await Promise.all(days.map(async day => {
    const path = `data/market/raw/${day.slice(0,4)}/${day}/daily.csv`;
    const binding = payload.source_files.find(item => item.path === path);
    if (!binding) return; // Never read an unbound newer market file.
    const bytes = await fetchPagesOnlyPath(path, "bytes");
    executableProfitExpect(await sha256Hex(bytes) === binding.sha256, "次日行情来源SHA不一致");
    tables.set(day, parseStrictCsvBytes(bytes, ["ts_code","trade_date","close","pre_close","vol"], "次日涨跌幅行情"));
  }));
  return nextDayMarketStatistics(sourceRows, payload.start_signal_date, payload.report_signal_date, summary.as_of_date, tables);
}

async function refreshNextDayMarketStatistics(loaded, current) {
  if (!loaded.marketInputs) return;
  loaded.marketPerformance = {status:"loading"};
  let timer;
  try {
    const cohorts = await Promise.race([loadNextDayMarketStatistics(loaded.marketInputs),
      new Promise((_, reject) => { timer = setTimeout(() => reject(new Error("次日行情加载超时，可刷新重试")), 20000); })]);
    if (!current()) return;
    loaded.marketPerformance = {status:"ready",cohorts};
  } catch (error) {
    if (!current()) return;
    loaded.marketPerformance = {status:"unavailable",reason:String(error?.message || error)};
  } finally { clearTimeout(timer); }
  if (current()) renderCompactDashboard();
}

function renderNextDayMarketMetrics(performance, rank) {
  const tone = value => value > 0 ? "positive" : value < 0 ? "negative" : "";
  const c = performance?.status === "ready" && performance.cohorts.find(c => c.rank === rank);
  if (!c) return `<dd class="success-sample">${performance?.status === "loading" ? "次日涨跌统计加载中" : "次日涨跌统计暂不可用"}</dd>`;
  return `<dd class="market-metric"><span>上涨率</span><strong>${pct(c.upRate)} <small>(${c.up}/${c.valid})</small></strong></dd>
    <dd class="market-metric"><span>平均涨跌幅</span><strong class="${tone(c.mean)}">${signedPct(c.mean)}</strong></dd>
    <dd class="market-metric"><span>中位涨跌幅</span><strong class="${tone(c.median)}">${signedPct(c.median)}</strong></dd>
    <dd class="success-sample">有效 ${c.valid} · 待验证 ${c.pending} · 缺行情 ${c.missing}</dd>`;
